-- ============================================================
--  VISTAS / REPORTES  –  Base de datos: suicide_rate
--  16 vistas analíticas sobre tasas de suicidio en México
-- ============================================================

-- VISTA 1: Resumen nacional por año
-- Descripción: Muestra el total de casos y la tasa nacional de suicidio (hombres, mujeres y total) para cada año, usando únicamente el registro 
-- agregado nacional (cve_entity = 0).
CREATE OR REPLACE VIEW vw_yearly_national_report AS
SELECT
    s.year_date                            AS year_date,
    s.male                            AS cases_male,
    s.female                          AS cases_female,
    s.unknown_gender                         AS cases_unknown_sex,
    s.total                           AS total_cases,
    ROUND(s.rate_male,   4)           AS male_rate,
    ROUND(s.rate_female, 4)           AS female_rate,
    ROUND(s.rate_total,  4)           AS total_rate
FROM suicide  s
JOIN entity   e ON e.cve_entity = s.cve_entity
WHERE e.is_national = TRUE
ORDER BY s.year_date;

-- VISTA 2: Tasa de suicidio por entidad (promedio histórico)
-- Descripción: Ranking de entidades federativas ordenadas de mayor a menor según su tasa promedio histórica de suicidio total (por 100,000 hab.), 
-- excluyendo el agregado nacional.
CREATE OR REPLACE VIEW vw_ranking_entity_average_rate AS
SELECT
    e.ent_name                              AS entity,
    COUNT(s.year_date)                       AS year_by_dates,
    ROUND(AVG(s.rate_total),  4)        AS total_average_rate,
    ROUND(AVG(s.rate_male),   4)        AS total_average_rate_male,
    ROUND(AVG(s.rate_female), 4)        AS total_average_rate_female,
    SUM(s.total)                        AS total_historic_cases
FROM suicide s
JOIN entity  e ON e.cve_entity = s.cve_entity
WHERE e.is_national = FALSE
GROUP BY e.cve_entity, e.ent_name
ORDER BY total_average_rate DESC;

-- VISTA 3: Evolución anual por entidad
-- Descripción: Serie de tiempo completa de casos y tasas por entidad y año, útil para gráficas de tendencia. Excluye el agregado nacional.
CREATE OR REPLACE VIEW vw_time_series_entity AS
SELECT
    e.ent_name                      AS entity,
    s.year_date                      AS year_date,
    s.total                     AS total_cases,
    s.male                      AS male_cases,
    s.female                    AS female_cases,
    ROUND(s.rate_total,  4)     AS total_rate,
    ROUND(s.rate_male,   4)     AS male_rate,
    ROUND(s.rate_female, 4)     AS female_rate
FROM suicide s
JOIN entity  e ON e.cve_entity = s.cve_entity
WHERE e.is_national = FALSE
ORDER BY e.ent_name, s.year_date;

-- VISTA 4: Top 5 entidades con mayor tasa en el último año disponible
-- Descripción: Las cinco entidades con la tasa de suicidio más alta en el año más reciente registrado en la tabla suicide.
CREATE OR REPLACE VIEW vw_top5_entities_last_year AS
SELECT
    e.ent_name                          AS entity,
    s.year_date                          AS year_date,
    s.total                         AS total_cases,
    ROUND(s.rate_total,  4)         AS total_rate,
    ROUND(s.rate_male,   4)         AS male_rate,
    ROUND(s.rate_female, 4)         AS female_rate
FROM suicide s
JOIN entity  e ON e.cve_entity = s.cve_entity
WHERE e.is_national = FALSE
  AND s.year_date = (SELECT MAX(year_date) FROM suicide WHERE cve_entity != 0)
ORDER BY s.rate_total DESC
LIMIT 5;

-- VISTA 5: Brecha de género por entidad y año
-- Descripción: Calcula la diferencia absoluta y relativa entre la tasa masculina y femenina de suicidio (brecha de género), indicando qué 
-- tan pronunciada es la diferencia por sexo.
CREATE OR REPLACE VIEW vw_gender_entity_gap AS
SELECT
    e.ent_name                                                    AS entity,
    s.year_date                                                   AS year_date,
    ROUND(s.rate_male,   4)                                       AS male_rate,
    ROUND(s.rate_female, 4)                                       AS female_rate,
    ROUND(s.rate_male - s.rate_female, 4)                         AS real_gap,
    CASE
        WHEN s.rate_female > 0
        THEN ROUND(s.rate_male / s.rate_female, 2)
        ELSE NULL
    END                                                           AS male_female_ratio
FROM suicide s
JOIN entity  e ON e.cve_entity = s.cve_entity
WHERE e.is_national = FALSE
  AND s.rate_male   IS NOT NULL
  AND s.rate_female IS NOT NULL
ORDER BY real_gap DESC;

-- VISTA 6: Variación interanual de la tasa nacional
-- Descripción: Calcula el cambio año a año en la tasa nacional de suicidio total, en puntos absolutos y en porcentaje, 
-- para identificar tendencias de aumento o disminución.
CREATE OR REPLACE VIEW vw_national_year_by_year_variation AS
SELECT
    curr.year_date                                                        AS year_date,
    ROUND(curr.rate_total, 4)                                        AS total_rate,
    ROUND(prev.rate_total, 4)                                        AS rate_past_year,
    ROUND(curr.rate_total - prev.rate_total, 4)                     AS absolute_change,
    CASE
        WHEN prev.rate_total > 0
        THEN ROUND(((curr.rate_total - prev.rate_total) / prev.rate_total) * 100, 2)
        ELSE NULL
    END                                                              AS porcentual_change
FROM suicide curr
JOIN suicide prev
  ON prev.cve_entity = curr.cve_entity
 AND prev.year_date       = curr.year_date - 1
JOIN entity e ON e.cve_entity = curr.cve_entity
WHERE e.is_national = TRUE
ORDER BY curr.year_date;

-- VISTA 7: Relación suicidio – desempleo por entidad y año
-- Descripción: Cruza la tasa de suicidio total con la tasa de desempleo total por entidad y año, para explorar posibles correlaciones entre ambas variables.
CREATE OR REPLACE VIEW vw_suicide_vs_unemployment AS
SELECT
    e.ent_name                      AS entity,
    s.year_date                     AS year_date,
    ROUND(s.rate_total,  4)         AS suicide_rate,
    ROUND(s.rate_male,   4)         AS male_suicide_rate,
    ROUND(s.rate_female, 4)         AS female_suicide_rate,
    ROUND(u.rate_total,  3)         AS unemployment_rate,
    ROUND(u.rate_male,   3)         AS male_unemployment_rate,
    ROUND(u.rate_female, 3)         AS female_unemployment_rate
FROM suicide      s
JOIN entity       e ON e.cve_entity = s.cve_entity
JOIN unemployment u ON u.cve_entity = s.cve_entity AND u.year_date = s.year_date
WHERE e.is_national = FALSE
ORDER BY e.ent_name, s.year_date;

-- VISTA 8: Entidades con mayor crecimiento de tasa (primer vs último año)
-- Descripción: Compara la tasa de suicidio del año más antiguo con la del año más reciente por entidad, para identificar
--   cuáles han mostrado el mayor incremento histórico.
CREATE OR REPLACE VIEW vw_historic_entity_growth AS
WITH min_max_years AS (
    SELECT 
        MIN(year_date) AS min_year,
        MAX(year_date) AS max_year
    FROM suicide
    WHERE cve_entity != 0
)
SELECT
    e.ent_name AS entity,
    s_ini.year_date AS start_year,
    ROUND(s_ini.rate_total, 4) AS start_rate,
    s_fin.year_date AS final_year,
    ROUND(s_fin.rate_total, 4) AS final_rate,
    ROUND(s_fin.rate_total - s_ini.rate_total, 4) AS absolute_change,
    CASE
        WHEN s_ini.rate_total > 0
        THEN ROUND(((s_fin.rate_total - s_ini.rate_total) / s_ini.rate_total) * 100, 2)
        ELSE NULL
    END AS percentage_change
FROM entity e
CROSS JOIN min_max_years mm
JOIN suicide s_ini ON s_ini.cve_entity = e.cve_entity AND s_ini.year_date = mm.min_year
JOIN suicide s_fin ON s_fin.cve_entity = e.cve_entity AND s_fin.year_date = mm.max_year
WHERE e.is_national = FALSE
ORDER BY absolute_change DESC;

-- VISTA 9: Casos totales acumulados por entidad
-- Descripción: Suma todos los casos registrados históricamente por entidad (hombres, mujeres, desconocidos y total), 
-- útil para reportes de carga absoluta de mortalidad.
CREATE OR REPLACE VIEW vw_accomulated_entity_cases AS
SELECT
    e.ent_name                  AS entity,
    SUM(s.male)                 AS total_male,
    SUM(s.female)               AS total_female,
    SUM(s.unknown_gender)       AS total_unknown,
    SUM(s.total)                AS total_cases,
    MIN(s.year_date)            AS start_year,
    MAX(s.year_date)            AS last_year
FROM suicide s
JOIN entity  e ON e.cve_entity = s.cve_entity
WHERE e.is_national = FALSE
GROUP BY e.cve_entity, e.ent_name
ORDER BY total_cases DESC;

-- VISTA 10: Tasa de suicidio por décadas (promedio decenal)
-- Descripción: Agrupa los datos por década (1990s, 2000s, 2010s, 2020s) y calcula la tasa promedio nacional, para analizar 
-- cambios estructurales en períodos largos.
CREATE OR REPLACE VIEW vw_average_per_decade_national AS
SELECT
    CONCAT(FLOOR(s.year_date / 10) * 10, 's')   AS decade,
    COUNT(DISTINCT s.year_date)                 AS year_per_decade,
    ROUND(AVG(s.rate_total),  4)                AS total_average_rate,
    ROUND(AVG(s.rate_male),   4)                AS male_average_rate,
    ROUND(AVG(s.rate_female), 4)                AS female_average_rate,
    SUM(s.total)                                AS cases_per_decade
FROM suicide s
JOIN entity  e ON e.cve_entity = s.cve_entity
WHERE e.is_national = TRUE
GROUP BY FLOOR(s.year_date / 10)
ORDER BY decade;

-- VISTA 11: Entidades con tasa femenina más alta (promedio histórico)
-- Descripción: Ranking de entidades ordenadas por la tasa promedio histórica de suicidio femenino, para visibilizar las entidades con mayor afectación en mujeres.
CREATE OR REPLACE VIEW vw_ranking_female_rate AS
SELECT
    e.ent_name                              AS entity,
    ROUND(AVG(s.rate_female), 4)        AS female_average_rate,
    ROUND(MIN(s.rate_female), 4)        AS female_minimum_rate,
    ROUND(MAX(s.rate_female), 4)        AS female_maximum_rate,
    SUM(s.female)                       AS total_female_cases
FROM suicide s
JOIN entity  e ON e.cve_entity = s.cve_entity
WHERE e.is_national = FALSE
  AND s.rate_female IS NOT NULL
GROUP BY e.cve_entity, e.ent_name
ORDER BY female_average_rate DESC;

-- VISTA 12: Entidades con tasa masculina más alta (promedio histórico)
-- Descripción: Ranking de entidades ordenadas por la tasa promedio histórica de suicidio masculino.
CREATE OR REPLACE VIEW vw_ranking_male_rate AS
SELECT
    e.ent_name                              AS entity,
    ROUND(AVG(s.rate_male), 4)          AS male_average_rate,
    ROUND(MIN(s.rate_male), 4)          AS male_minimum_rate,
    ROUND(MAX(s.rate_male), 4)          AS male_maximum_rate,
    SUM(s.male)                         AS total_male_cases
FROM suicide s
JOIN entity  e ON e.cve_entity = s.cve_entity
WHERE e.is_national = FALSE
  AND s.rate_male IS NOT NULL
GROUP BY e.cve_entity, e.ent_name
ORDER BY male_average_rate DESC;

-- VISTA 13: Año con mayor tasa por entidad (pico histórico)
-- Descripción: Para cada entidad muestra el año en que se registró la tasa de suicidio total más alta, junto con el valor de dicha tasa y 
-- el total de casos en ese año.
CREATE OR REPLACE VIEW vw_historic_peak_per_entity AS
SELECT
    e.ent_name                      AS entity,
    s.year_date                     AS peak_year,
    s.total                         AS cases_in_peak,
    ROUND(s.rate_total,  4)         AS total_peak_rate,
    ROUND(s.rate_male,   4)         AS total_peak_male,
    ROUND(s.rate_female, 4)         AS total_peak_female
FROM suicide s
JOIN entity  e ON e.cve_entity = s.cve_entity
WHERE e.is_national = FALSE
  AND s.rate_total = (
        SELECT MAX(s2.rate_total)
        FROM suicide s2
        WHERE s2.cve_entity = s.cve_entity
  )
ORDER BY total_peak_rate DESC;

-- VISTA 14: Comparativo regional Norte / Centro / Sur
-- Descripción: Agrupa las entidades en tres macrorregiones geográficas y calcula la tasa promedio histórica por región, sexo y total, para comparativas a 
-- gran escala.
--   Norte:  Baja California, BCS, Sonora, Chihuahua, Coahuila, Nuevo León, Tamaulipas, Durango, Sinaloa, Zacatecas, Nayarit.
--   Centro: Jalisco, Colima, Aguascalientes, Guanajuato, Querétaro, Michoacán, Estado de México, CDMX, Hidalgo, Tlaxcala, Morelos, Puebla, San Luis Potosí.
--   Sur:    Guerrero, Oaxaca, Chiapas, Veracruz, Tabasco, Campeche, Yucatán, Quintana Roo.
CREATE OR REPLACE VIEW vw_regional_ccomparative AS
SELECT
    CASE
        WHEN e.cve_entity IN (2,3,26,8,5,19,28,10,25,32,18)  THEN 'Norte'
        WHEN e.cve_entity IN (14,6,1,11,22,16,15,9,13,29,17,21,24) THEN 'Centro'
        WHEN e.cve_entity IN (12,20,7,30,27,4,31,23)          THEN 'Sur'
    END                                 AS region,
    e.ent_name                              AS entity,
    ROUND(AVG(s.rate_total),  4)        AS total_average_rate,
    ROUND(AVG(s.rate_male),   4)        AS male_average_rate,
    ROUND(AVG(s.rate_female), 4)        AS female_average_rate,
    SUM(s.total)                        AS historic_cases
FROM suicide s
JOIN entity  e ON e.cve_entity = s.cve_entity
WHERE e.is_national = FALSE
GROUP BY region, e.cve_entity, e.ent_name
ORDER BY region, total_average_rate DESC;

-- VISTA 15: Tasa de suicidio relativa a la población (densidad de casos)
-- Descripción: Para cada entidad y año calcula qué proporción de la población total corresponde a un caso de suicidio (inverso de la tasa), lo que ayuda a 
-- expresar el impacto en términos de "1 caso por cada N habitantes".
CREATE OR REPLACE VIEW vw_case_density_per_population AS
SELECT
    e.ent_name                           AS entity,
    s.year_date                          AS year_date,
    p.pop_total                          AS total_pop,
    s.total                              AS total_cases,
    ROUND(s.rate_total, 4)               AS rate_per_100k,
    CASE
        WHEN s.total > 0
        THEN ROUND(p.pop_total / s.total, 0)
        ELSE NULL
    END                             AS pop_per_case
FROM suicide    s
JOIN entity     e ON e.cve_entity = s.cve_entity
JOIN population p ON p.cve_entity = s.cve_entity AND p.year_date = s.year_date
WHERE e.is_national = FALSE
ORDER BY e.ent_name, s.year_date;